1	import type { InvestmentCommitteeState } from "./analysis";
2	import type { Claim } from "./evidence";
3	
4	/**
5	 * Referential-integrity helpers for evidence.
6	 *
7	 * The core invariant of Sonar AI: every material graph edge and thesis claim
8	 * resolves to a known evidence record. A model output is invalid until this
9	 * holds. These pure functions let both the contract tests and the orchestrator's
10	 * evidence gate enforce it the same way.
11	 */
12	
13	function claimEvidenceIds(claims: readonly Claim[] | undefined): string[] {
14	  return (claims ?? []).flatMap((c) => c.evidenceIds);
15	}
16	
17	/**
18	 * Every evidence ID referenced anywhere in the committee state — events, graph
19	 * nodes and edges, proposed actions, agent claims, and activities.
20	 */
21	export function collectReferencedEvidenceIds(
22	  state: InvestmentCommitteeState,
23	): Set<string> {
24	  const ids: string[] = [];
25	
26	  for (const event of state.materialEvents) ids.push(...event.evidenceIds);
27	  for (const node of state.graph.nodes) ids.push(...node.evidenceIds);
28	  for (const edge of state.graph.edges) ids.push(...edge.evidenceIds);
29	  for (const action of state.proposedActions) ids.push(...action.evidenceIds);
30	  for (const report of state.fundamentalReports)
31	    ids.push(...claimEvidenceIds(report.claims));
32	  ids.push(...claimEvidenceIds(state.marketContext?.claims));
33	
34	  const rec = state.finalRecommendation;
35	  if (rec) {
36	    ids.push(...claimEvidenceIds(rec.bull));
37	    ids.push(...claimEvidenceIds(rec.context));
38	    ids.push(...claimEvidenceIds(rec.bear));
39	    for (const action of rec.actions) ids.push(...action.evidenceIds);
40	  }
41	
42	  ids.push(...claimEvidenceIds(state.bearCase?.claims));
43	  for (const activity of state.activities) ids.push(...activity.evidenceIds);
44	
45	  return new Set(ids);
46	}
47	
48	/**
49	 * Referenced evidence IDs that do not resolve to a record in `state.evidence`.
50	 * An empty array means the state is referentially sound.
51	 */
52	export function findDanglingEvidenceIds(
53	  state: InvestmentCommitteeState,
54	): string[] {
55	  const known = new Set(state.evidence.map((e) => e.id));
56	  const referenced = collectReferencedEvidenceIds(state);
57	  return [...referenced].filter((id) => !known.has(id));
58	}
