1	import type { PortfolioSnapshot, ProposedAction } from "@sonar-ai/core";
2	
3	/**
4	 * Risk math runs in weight-space (fractions of NAV), independent of prices.
5	 * A `ProposedAction.targetWeight` is the resulting weight for that instrument
6	 * after the action, so the proposed portfolio is the current position weights
7	 * overridden by any action targets.
8	 */
9	export type WeightMap = Map<string, number>;
10	
11	/** Current weights per instrument from a portfolio snapshot. */
12	export function currentWeights(portfolio: PortfolioSnapshot): WeightMap {
13	  const map: WeightMap = new Map();
14	  for (const p of portfolio.positions) map.set(p.instrumentId, p.weight);
15	  return map;
16	}
17	
18	/**
19	 * Proposed weights = current weights with each action's `targetWeight` applied
20	 * as the new absolute weight for its instrument. `overrides` lets the engine
21	 * substitute post-resize weights for specific actions.
22	 */
23	export function proposedWeights(
24	  portfolio: PortfolioSnapshot,
25	  actions: readonly ProposedAction[],
26	  overrides?: ReadonlyMap<string, number>,
27	): WeightMap {
28	  const map = currentWeights(portfolio);
29	  for (const a of actions) {
30	    const w = overrides?.get(a.id) ?? a.targetWeight;
31	    map.set(a.instrumentId, w);
32	  }
33	  return map;
34	}
35	
36	/** Total invested weight (sum of all position weights). */
37	export function investedWeight(weights: WeightMap): number {
38	  let sum = 0;
39	  for (const w of weights.values()) sum += w;
40	  return sum;
41	}
