1	import type {
2	  Instrument,
3	  Mandate,
4	  PortfolioSnapshot,
5	  ProposedAction,
6	  RiskBreachCode,
7	  RiskCheck,
8	  RiskMetrics,
9	  RiskReport,
10	} from "@sonar-ai/core";
11	import { PORTFOLIO_LEVEL_ACTION_ID } from "@sonar-ai/core";
12	import { comparePortfolios } from "./compare";
13	import { computeMetrics, type InstrumentStats } from "./metrics";
14	import { applyPositionLimit } from "./rules/position-limit";
15	import {
16	  checkCashFloor,
17	  checkSectorLimits,
18	  checkTurnover,
19	} from "./rules/portfolio-limits";
20	import { validateAction } from "./rules/validate";
21	import { runStressTest, type StressScenario } from "./stress";
22	import { investedWeight, proposedWeights } from "./weights";
23	
24	export interface EvaluateInput {
25	  portfolio: PortfolioSnapshot;
26	  mandate: Mandate;
27	  actions: readonly ProposedAction[];
28	  instruments: readonly Instrument[];
29	  instrumentStats?: InstrumentStats;
30	  stressScenarios?: readonly StressScenario[];
31	  /** Stable id for the produced report (the Risk Officer stage assigns one). */
32	  reportId?: string;
33	}
34	
35	/**
36	 * The deterministic Risk Officer. Pure: no IO, no clock, no randomness — the
37	 * same input always yields the same {@link RiskReport}.
38	 *
39	 * Enforcement model:
40	 * - DATA_INVALID  → the action is rejected and excluded; a hard block.
41	 * - POSITION_LIMIT_BREACH → the action is resized to the limit (soft, the run
42	 *   continues).
43	 * - RISK_MANDATE_BREACH (sector / cash floor / turnover) → a hard block that
44	 *   stops the proposal for Portfolio Manager revision.
45	 *
46	 * `numbers` on every check carries the reproducible figures behind the verdict.
47	 */
48	export function evaluateProposal(input: EvaluateInput): RiskReport {
49	  const {
50	    portfolio,
51	    mandate,
52	    actions,
53	    instruments,
54	    instrumentStats = {},
55	    stressScenarios = [],
56	    reportId = "risk_report",
57	  } = input;
58	
59	  const nav = portfolio.nav.amount;
60	  const currency = portfolio.baseCurrency;
61	
62	  const checks: RiskCheck[] = [];
63	  const hardBlocks = new Set<RiskBreachCode>();
64	  const overrides = new Map<string, number>();
65	  const appliedActions: ProposedAction[] = [];
66	  let sellNotional = 0;
67	
68	  // ── Per-action checks ──────────────────────────────────────────────────────
69	  for (const action of actions) {
70	    const check: RiskCheck = {
71	      id: `rsk_${action.id}`,
72	      actionId: action.id,
73	      result: "pass",
74	      detail: "",
75	      numbers: {},
76	    };
77	
78	    const validation = validateAction(action, mandate, nav);
79	    if (!validation.ok) {
80	      check.result = "reject";
81	      check.breachCode = "DATA_INVALID";
82	      check.detail = validation.detail;
83	      check.numbers = validation.numbers;
84	      hardBlocks.add("DATA_INVALID");
85	      checks.push(check);
86	      continue; // excluded from the proposed portfolio
87	    }
88	
89	    const pl = applyPositionLimit(action, mandate, nav);
90	    if (pl.resized) {
91	      check.result = "resize";
92	      check.breachCode = "POSITION_LIMIT_BREACH";
93	      check.detail = `${action.instrumentId} ${pct(pl.numbers.proposedWeight)} exceeds the ${pct(
94	        pl.numbers.positionLimit,
95	      )} max-position limit; resized to ${pct(pl.numbers.resizedWeight)}.`;
96	      check.numbers = pl.numbers;
97	      check.resizedAmount = { amount: pl.amount, currency };
98	      overrides.set(action.id, pl.weight);
99	    } else {
100	      check.result = "pass";
101	      check.detail = `${action.instrumentId} ${pct(action.targetWeight)} within limits.`;
102	      check.numbers = pl.numbers;
103	    }
104	
105	    if (action.side === "sell") sellNotional += pl.amount;
106	    appliedActions.push(action);
107	    checks.push(check);
108	  }
109	
110	  // ── Portfolio-level view (post-resize, valid actions only) ─────────────────
111	  const proposed = proposedWeights(portfolio, appliedActions, overrides);
112	  const baseMetrics = computeMetrics(proposed, instruments, instrumentStats);
113	  const comparison = comparePortfolios(portfolio, proposed);
114	  const invested = investedWeight(proposed);
115	
116	  for (const breach of checkSectorLimits(baseMetrics.sectorExposure, mandate)) {
117	    checks.push({
118	      id: `rsk_sector_${breach.sector}`,
119	      actionId: PORTFOLIO_LEVEL_ACTION_ID,
120	      result: "reject",
121	      breachCode: "RISK_MANDATE_BREACH",
122	      detail: `Sector ${breach.sector} exposure ${pct(breach.exposure)} exceeds the ${pct(
123	        breach.limit,
124	      )} sector limit.`,
125	      numbers: { sectorExposure: breach.exposure, sectorLimit: breach.limit },
126	    });
127	    hardBlocks.add("RISK_MANDATE_BREACH");
128	  }
129	
130	  const cash = checkCashFloor(invested, mandate);
131	  if (!cash.ok) {
132	    checks.push({
133	      id: "rsk_cash_floor",
134	      actionId: PORTFOLIO_LEVEL_ACTION_ID,
135	      result: "reject",
136	      breachCode: "RISK_MANDATE_BREACH",
137	      detail: `Cash ratio ${pct(cash.cashRatio)} is below the ${pct(cash.minCashRatio)} floor.`,
138	      numbers: { cashRatio: cash.cashRatio, minCashRatio: cash.minCashRatio },
139	    });
140	    hardBlocks.add("RISK_MANDATE_BREACH");
141	  }
142	
143	  const turnover = checkTurnover(sellNotional, nav, mandate);
144	  if (!turnover.ok) {
145	    checks.push({
146	      id: "rsk_turnover",
147	      actionId: PORTFOLIO_LEVEL_ACTION_ID,
148	      result: "reject",
149	      breachCode: "RISK_MANDATE_BREACH",
150	      detail: `Turnover ${pct(turnover.turnover)} exceeds the ${pct(turnover.maxTurnover)} per-event limit.`,
151	      numbers: { turnover: turnover.turnover, maxTurnover: turnover.maxTurnover },
152	    });
153	    hardBlocks.add("RISK_MANDATE_BREACH");
154	  }
155	
156	  // Surface the current value of every mandate limit in the metrics.
157	  const metrics: RiskMetrics = {
158	    ...baseMetrics,
159	    cashRatio: cash.cashRatio,
160	    turnover: turnover.turnover,
161	  };
162	
163	  const stress = stressScenarios.map((s) =>
164	    runStressTest(proposed, nav, currency, s, instrumentStats),
165	  );
166	
167	  return {
168	    id: reportId,
169	    metrics,
170	    stress,
171	    checks,
172	    comparison,
173	    hardBlocks: [...hardBlocks],
174	  };
175	}
