1	import type { Instrument, RiskMetrics } from "@sonar-ai/core";
2	import type { WeightMap } from "./weights";
3	
4	/**
5	 * The weight-derived subset of {@link RiskMetrics}. `cashRatio` and `turnover`
6	 * are mandate-compliance figures the engine adds once it knows the invested
7	 * total and sell-side notional, so `computeMetrics` returns everything else.
8	 */
9	export type PortfolioRiskMetrics = Omit<RiskMetrics, "cashRatio" | "turnover">;
10	
11	/**
12	 * Optional per-instrument risk statistics. Absent an entry, an instrument is
13	 * treated as beta 1.0, volatility 0. These feed simplified portfolio metrics.
14	 */
15	export type InstrumentStats = Record<
16	  string,
17	  { volatility: number; beta: number }
18	>;
19	
20	function sectorOf(instrumentId: string, instruments: readonly Instrument[]): string {
21	  return instruments.find((i) => i.id === instrumentId)?.sector ?? "Unknown";
22	}
23	
24	/** Exposure by sector name, each a fraction of NAV. */
25	export function sectorExposure(
26	  weights: WeightMap,
27	  instruments: readonly Instrument[],
28	): Record<string, number> {
29	  const out: Record<string, number> = {};
30	  for (const [instrumentId, w] of weights) {
31	    if (w === 0) continue;
32	    const sector = sectorOf(instrumentId, instruments);
33	    out[sector] = (out[sector] ?? 0) + w;
34	  }
35	  return out;
36	}
37	
38	/** Concentration = the largest single-position weight (0 for an empty book). */
39	export function concentration(weights: WeightMap): number {
40	  let max = 0;
41	  for (const w of weights.values()) max = Math.max(max, w);
42	  return max;
43	}
44	
45	/**
46	 * Simplified portfolio beta: the weight-weighted average of instrument betas.
47	 * MVP metric — it is not a covariance model, and it is labeled as such in docs.
48	 */
49	export function portfolioBeta(weights: WeightMap, stats: InstrumentStats): number {
50	  let beta = 0;
51	  for (const [id, w] of weights) beta += w * (stats[id]?.beta ?? 1);
52	  return beta;
53	}
54	
55	/**
56	 * Simplified portfolio volatility: the weight-weighted average of instrument
57	 * volatilities. MVP metric, not a covariance-based figure.
58	 */
59	export function portfolioVolatility(
60	  weights: WeightMap,
61	  stats: InstrumentStats,
62	): number {
63	  let vol = 0;
64	  for (const [id, w] of weights) vol += w * (stats[id]?.volatility ?? 0);
65	  return vol;
66	}
67	
68	/**
69	 * Compute the weight-derived metrics for a proposed weight map. The engine
70	 * augments the result with `cashRatio` and `turnover` to form a full
71	 * {@link RiskMetrics}.
72	 */
73	export function computeMetrics(
74	  weights: WeightMap,
75	  instruments: readonly Instrument[],
76	  stats: InstrumentStats = {},
77	): PortfolioRiskMetrics {
78	  return {
79	    volatility: portfolioVolatility(weights, stats),
80	    beta: portfolioBeta(weights, stats),
81	    concentration: concentration(weights),
82	    sectorExposure: sectorExposure(weights, instruments),
83	  };
84	}
