1	import type { Mandate } from "@sonar-ai/core";
2	
3	const EPS = 1e-9;
4	
5	export interface SectorBreach {
6	  sector: string;
7	  exposure: number;
8	  limit: number;
9	}
10	
11	/**
12	 * Sector exposures over `maxSectorExposure`. Unlike the position limit, a sector
13	 * breach is a HARD BLOCK — the Risk Officer stops the proposal and the Portfolio
14	 * Manager must revise; the engine does not silently trim it.
15	 */
16	export function checkSectorLimits(
17	  sectorExposure: Record<string, number>,
18	  mandate: Mandate,
19	): SectorBreach[] {
20	  const limit = mandate.limits.maxSectorExposure;
21	  return Object.entries(sectorExposure)
22	    .filter(([, exposure]) => exposure > limit + EPS)
23	    .map(([sector, exposure]) => ({ sector, exposure, limit }))
24	    .sort((a, b) => a.sector.localeCompare(b.sector));
25	}
26	
27	export interface CashFloorOutcome {
28	  ok: boolean;
29	  cashRatio: number;
30	  minCashRatio: number;
31	}
32	
33	/** The minimum-cash floor. A breach is a hard block. */
34	export function checkCashFloor(
35	  investedWeight: number,
36	  mandate: Mandate,
37	): CashFloorOutcome {
38	  const minCashRatio = mandate.limits.minCashRatio;
39	  const cashRatio = 1 - investedWeight;
40	  return { ok: cashRatio >= minCashRatio - EPS, cashRatio, minCashRatio };
41	}
42	
43	export interface TurnoverOutcome {
44	  ok: boolean;
45	  turnover: number;
46	  maxTurnover: number;
47	}
48	
49	/**
50	 * Turnover measures churn of EXISTING holdings, not deployment of cash. It is
51	 * the sell-side notional rotated out of current positions, as a fraction of
52	 * NAV. Deploying an all-cash book into new positions therefore has turnover 0;
53	 * only later rebalances that sell existing holdings count. A breach is a hard
54	 * block.
55	 */
56	export function checkTurnover(
57	  sellNotional: number,
58	  nav: number,
59	  mandate: Mandate,
60	): TurnoverOutcome {
61	  const maxTurnover = mandate.limits.maxTurnoverPerEvent;
62	  const turnover = nav > 0 ? sellNotional / nav : 0;
63	  return { ok: turnover <= maxTurnover + EPS, turnover, maxTurnover };
64	}
