11	/**
12	 * DATA_INVALID guard for a single action. A proposal is only as trustworthy as
13	 * its inputs: the currency must match the mandate, the target weight must be a
14	 * fraction in [0, 1], and the stated amount must agree with `targetWeight × NAV`
15	 * within 1% of NAV. Anything else is rejected before it can size a trade.
16	 */
17	export function validateAction(
18	  action: ProposedAction,
19	  mandate: Mandate,
20	  nav: number,
21	): ActionValidation {
22	  const numbers: Record<string, number> = {
23	    targetWeight: action.targetWeight,
24	    amount: action.amount.amount,
25	  };
26	
27	  if (action.amount.currency !== mandate.baseCurrency) {
28	    return {
29	      ok: false,
30	      detail: `Action currency ${action.amount.currency} does not match mandate base ${mandate.baseCurrency}.`,
31	      numbers,
32	    };
33	  }
34	  if (
35	    !Number.isFinite(action.targetWeight) ||
36	    action.targetWeight < -EPS ||
37	    action.targetWeight > 1 + EPS
38	  ) {
39	    return {
40	      ok: false,
41	      detail: `Target weight ${action.targetWeight} is outside [0, 1].`,
42	      numbers,
43	    };
44	  }
45	
46	  const expected = action.targetWeight * nav;
47	  const tolerance = Math.max(1, 0.01 * nav);
48	  numbers.expectedAmount = expected;
49	  if (Math.abs(action.amount.amount - expected) > tolerance) {
50	    return {
51	      ok: false,
52	      detail: `Amount ${action.amount.amount} disagrees with targetWeight×NAV (${expected}).`,
53	      numbers,
54	    };
55	  }
56	
57	  return { ok: true, detail: "Action inputs are consistent.", numbers };
58	}
