5	/**
6	 * A deterministic stress scenario. Either supply per-instrument return shocks
7	 * (fractions, e.g. -0.2 for -20%) or a broad `marketShock` applied through
8	 * portfolio beta. Per-instrument shocks take precedence where present.
9	 */
10	export interface StressScenario {
11	  name: string;
12	  shockByInstrument?: Record<string, number>;
13	  marketShock?: number;
14	}
