16	/** Apply one stress scenario to a proposed weight map. */
17	export function runStressTest(
18	  weights: WeightMap,
19	  navAmount: number,
20	  currency: Currency,
21	  scenario: StressScenario,
22	  stats: InstrumentStats = {},
23	): StressResult {
24	  let pct = 0;
25	  const perInstrument = scenario.shockByInstrument ?? {};
26	
27	  for (const [id, w] of weights) {
28	    if (id in perInstrument) {
29	      pct += w * (perInstrument[id] ?? 0);
30	    } else if (scenario.marketShock !== undefined) {
31	      pct += w * scenario.marketShock * (stats[id]?.beta ?? 1);
32	    }
33	  }
34	
35	  const navImpact = pct * navAmount;
36	  return {
37	    scenario: scenario.name,
38	    navImpact: { amount: Math.round(navImpact * 100) / 100, currency },
39	    navImpactPct: pct,
40	  };
